import sys

MOD = 998244353

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    N = int(data[0])
    M = int(data[1])
    S = data[2]

    size = 1 << N

    # vals[mask][i] = LCS length of S[:i] and the processed string,
    # represented by the bitmask of positions where the DP row increases.
    vals = []
    for mask in range(size):
        arr = [0] * (N + 1)
        cnt = 0
        for i in range(1, N + 1):
            if (mask >> (i - 1)) & 1:
                cnt += 1
            arr[i] = cnt
        vals.append(arr)

    alphabet = "abcdefghijklmnopqrstuvwxyz"

    # Precompute transitions: for each state and each character,
    # aggregate how many characters lead to the same next state.
    trans = []
    for mask in range(size):
        f = vals[mask]
        d = {}
        for ch in alphabet:
            newmask = 0
            prev = 0  # new DP value for prefix length i-1
            for i in range(1, N + 1):
                match = 1 if S[i - 1] == ch else 0

                v = f[i]
                if prev > v:
                    v = prev
                cand = f[i - 1] + match
                if cand > v:
                    v = cand

                if v != prev:
                    newmask |= 1 << (i - 1)
                prev = v

            d[newmask] = d.get(newmask, 0) + 1
        trans.append(list(d.items()))

    pop = [m.bit_count() for m in range(size)]

    dp = [0] * size
    dp[0] = 1

    for _ in range(M):
        ndp = [0] * size
        for mask, val in enumerate(dp):
            if val:
                for nmask, cnt in trans[mask]:
                    ndp[nmask] += val * cnt
        for i in range(size):
            ndp[i] %= MOD
        dp = ndp

    ans = [0] * (N + 1)
    for mask, val in enumerate(dp):
        if val:
            ans[pop[mask]] = (ans[pop[mask]] + val) % MOD

    print(" ".join(map(str, ans)))

if __name__ == "__main__":
    solve()
