import sys

def main():
    tokens = sys.stdin.buffer.read().split()
    if not tokens:
        return

    it = iter(tokens)
    N = int(next(it))

    dice = []
    for _ in range(N):
        K = int(next(it))
        counts = {}
        for _ in range(K):
            a = int(next(it))
            counts[a] = counts.get(a, 0) + 1

        dice.append((K, counts, list(counts.items())))

    # Iterate over the smaller unique-value dictionary for each pair.
    dice.sort(key=lambda x: len(x[2]))

    ans = 0.0

    for i in range(N):
        Ki, _, items_i = dice[i]

        for j in range(i + 1, N):
            Kj, dj, _ = dice[j]
            get_count = dj.get

            common_weighted = 0
            for value, count_i in items_i:
                count_j = get_count(value)
                if count_j:
                    common_weighted += count_i * count_j

            prob = common_weighted / (Ki * Kj)
            if prob > ans:
                ans = prob

    print(f"{ans:.15f}")

if __name__ == "__main__":
